154	    private void validateInstantOrderBidInput(String buyerEmail, Long saleBidId, Long addressId, NotificationRequestDto paymentRequest) {
155	        if (buyerEmail == null || buyerEmail.trim().isEmpty()) {
156	            throw new FaqBidAccessDeniedException("구매자 이메일이 없습니다.");
157	        }
158	        if (saleBidId == null) {
159	            throw new StyleBidNotFoundException("판매 입찰 ID가 없습니다.");
160	        }
161	        if (addressId == null) {
162	            throw new InvalidFaqBidDataException("배송지 ID가 없습니다.");
163	        }
164	        if (paymentRequest == null) {
165	            throw new InvalidNotificationAddressDataException("결제 정보가 없습니다.");
166	        }
167	    }
