189	    private FaqBid createInstantOrderBid(Faq order, StyleBid saleBid, Style sale) {
190	        UserSize productSize = saleBid.getProductSize();
191	
192	        FaqBid orderBid = FaqBid.builder()
193	                .user(order.getUser())
194	                .productSize(productSize)
195	                .bidPrice(saleBid.getBidPrice())
196	                .status(BidStatus.MATCHED)
197	                .order(order)
198	                .sale(sale)
199	                .build();
200	
201	
202	        orderBid.assignOrder(order);
203	
204	
205	        orderBid.markAsInstantPurchase();
206	        return orderBidRepository.save(orderBid);
207	    }
