112	    public void processPaymentAndShipment(Long orderId, String userEmail, PayAndAddressRequestDto requestDto) {
113	        if (orderId == null) {
114	            throw new InvalidFaqDataException("주문 ID가 없습니다.");
115	        }
116	        if (userEmail == null || userEmail.trim().isEmpty()) {
117	            throw new FaqAccessDeniedException("사용자 정보가 없습니다.");
118	        }
119	        if (requestDto == null) {
120	            throw new InvalidNotificationAddressDataException("결제 및 배송 정보가 없습니다.");
121	        }
122	
123	        try {
124	
125	            Product user = userQueryService.findByEmail(userEmail);
126	            Faq order = orderRepository.findById(orderId)
127	                    .orElseThrow(() -> new FaqNotFoundException("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));
128	
129	
130	            if (!order.getUser().getId().equals(user.getId())) {
131	                throw new FaqAccessDeniedException("해당 사용자는 이 주문을 처리할 권한이 없습니다.");
132	            }
133	
134	
135	            validatePaymentShipmentRequest(requestDto);
136	
137	            try {
138	
139	                Notification payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
140	                order.assignPayment(payment);
141	            } catch (Exception e) {
142	                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
143	                throw new FaqNotificationProcessingFailedException("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
144	            }
145	
146	            try {
147	
148	                FaqAddress shipment = orderShipmentCommandService.createOrderShipment(
149	                        order,
150	                        requestDto.getReceiverName(),
151	                        requestDto.getReceiverPhone(),
152	                        requestDto.getPostalCode(),
153	                        requestDto.getAddress()
154	                );
155	                order.assignOrderShipment(shipment);
156	            } catch (Exception e) {
157	                log.error("배송 정보 처리 중 오류 발생: {}", e.getMessage(), e);
158	                throw new FaqAddressProcessingFailedException("배송 정보 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
159	            }
160	
161	            try {
162	
163	                if (requestDto.isWarehouseStorage()) {
164	
165	                    order.updateStatus(FaqStatus.PAYMENT_COMPLETED);
166	                    order.updateStatus(FaqStatus.PREPARING);
167	                    order.updateStatus(FaqStatus.IN_WAREHOUSE);
168	
169	
170	                    Notice warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
171	                    order.assignWarehouseStorage(warehouseStorage);
172	                    order.updateStatus(FaqStatus.COMPLETED);
173	                } else {
174	
175	                    order.updateStatus(FaqStatus.PAYMENT_COMPLETED);
176	                    order.updateStatus(FaqStatus.PREPARING);
