 58	    @Transactional
 59	    public Faq createOrderFromBid(Product user, UserSize productSize, int bidPrice) {
 60	        try {
 61	
 62	            if (user == null) {
 63	                throw new InvalidFaqDataException("사용자 정보가 없습니다.");
 64	            }
 65	            if (productSize == null) {
 66	                throw new UserSizeNotFoundException("상품 사이즈 정보가 없습니다.");
 67	            }
 68	            if (bidPrice <= 0) {
 69	                throw new InvalidBidPriceException("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
 70	            }
 71	
 72	
 73	            FaqItem orderItem = orderItemCommandService.createOrderItem(null, productSize, bidPrice);
 74	
 75	
 76	            Faq order = Faq.builder()
 77	                    .user(user)
 78	                    .totalAmount(bidPrice)
 79	                    .discountAmount(0)
 80	                    .usedPoints(0)
 81	                    .status(FaqStatus.PENDING_PAYMENT)
 82	                    .build();
 83	
 84	
 85	            order.addOrderItem(orderItem);
 86	
 87	
 88	            return orderRepository.save(order);
 89	        } catch (Exception e) {
 90	            if (e instanceof FaqException) {
 91	                throw e;
 92	            }
 93	            log.error("주문 생성 중 오류 발생: {}", e.getMessage(), e);
 94	            throw new FaqCreationFailedException("입찰에서 주문 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
 95	        }
 96	    }
