57	    57	    public Notification processPayment(Faq order, Product user, NotificationRequestDto requestDto) {
58	    58	        Instant start = Instant.now();
59	    59	        try {
60	    60	            validatePaymentRequest(order, user, requestDto);
61	    61	
62	    62	            log.info("결제 처리 시작: 주문ID={}, 사용자={}, 결제유형={}",
63	    63	                    order.getId(), user.getEmail(), requestDto.getResolvedPaymentType());
64	    64	
65	    65	            Notification payment;
66	    66	
67	    67	            switch (requestDto.getResolvedPaymentType()) {
68	    68	                case "CARD":
69	    69	                    payment = createCardPayment(order, user, (CardNotificationRequestDto) requestDto);
70	    70	                    break;
71	    71	                case "ACCOUNT":
72	    72	                    payment = createAccountPayment(order, user, (AccountNotificationRequestDto) requestDto);
73	    73	                    break;
74	    74	                case "GENERAL":
75	    75	                    payment = createGeneralPayment(order, user, (GeneralNotificationRequestDto) requestDto);
76	    76	                    break;
77	    77	                default:
78	    78	                    throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED,
79	    79	                            "유효하지 않은 결제 유형: " + requestDto.getPaymentType());
80	    80	            }
81	    81	
82	    82	
83	    83	            notifyUsersAndUpdateSaleStatus(order, payment);
84	    84	
85	    85	            log.info("결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
86	    86	                    order.getId(), payment.getId(), payment.getStatus());
87	    87	
88	    88	            return payment;
89	    89	        } catch (NotificationException e) {
90	    90	            log.error("결제 처리 실패: 주문ID={}, 사용자={}, 에러코드={}, 메시지={}",
91	    91	                    order != null ? order.getId() : "null",
92	    92	                    user != null ? user.getEmail() : "null",
93	    93	                    e.getErrorCode().getCode(), e.getMessage());
94	    94	            throw e;
95	    95	        } catch (Exception e) {
96	    96	            log.error("결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 사용자={}, 오류={}",
97	    97	                    order != null ? order.getId() : "null",
98	    98	                    user != null ? user.getEmail() : "null",
99	    99	                    e.getMessage(), e);
100	   100	            throw new NotificationProcessingException("결제 처리 중 오류가 발생했습니다: " + e.getMessage());
101	   101	        } finally {
102	   102	
103	   103	            Instant end = Instant.now();
