   269	    private void broadcastNotificationsToConnectedUsers(List<Product> users, List<Payment> notifications) {
   270	        int deliveredCount = 0;
   272	        for (Product user : users) {
   273	            String redisKey = REDIS_KEY_PREFIX + user.getEmail();
   275	            if (Boolean.TRUE.equals(redisTemplate.hasKey(redisKey))) {
   276	                try {
   278	                    List<PaymentDTO> userNotifications = notifications.stream()
   279	                            .filter(notification -> notification.getUser().getId().equals(user.getId()))
   280	                            .map(this::toDTO)
   281	                            .collect(Collectors.toList());
   284	                    messagingTemplate.convertAndSendToUser(
   285	                            user.getEmail(),
   286	                            WEBSOCKET_DESTINATION,
   287	                            userNotifications
   288	                    );
   289	                    deliveredCount++;
   290	                } catch (Exception e) {
   291	                    log.warn("사용자 알림 실시간 전송 실패: 사용자={}, 오류={}", user.getEmail(), e.getMessage());
   293	                }
   294	            }
   295	        }
   297	        log.info("실시간 알림 전송 완료: 총 {}명 중 {}명에게 전송됨", users.size(), deliveredCount);
   298	    }
   303	    private void sendRealTimeNotification(String email, PaymentDTO notification) {
   304	        String redisKey = REDIS_KEY_PREFIX + email;
   307	        if (Boolean.TRUE.equals(redisTemplate.hasKey(redisKey))) {
   308	            try {
   309	                messagingTemplate.convertAndSendToUser(
   310	                        email,
   311	                        WEBSOCKET_DESTINATION,
   312	                        notification
   313	                );
   314	                log.debug("알림 실시간 전송 완료: 사용자={}, 알림ID={}", email, notification.getId());
   315	            } catch (Exception e) {
   316	                log.warn("알림 실시간 전송 실패: 사용자={}, 알림ID={}, 오류={}",
   317	                        email, notification.getId(), e.getMessage());
   319	            }
   320	        } else {
   321	            log.debug("사용자 WebSocket 연결 없음: 사용자={}, 알림은 저장됨", email);
   322	        }
   323	    }
   328	    public void updateWebSocketConnectionTTL(String email) {
   329	        try {
   330	            if (email != null) {
   331	                String redisKey = REDIS_KEY_PREFIX + email;
   334	                Long remainingTime = redisTemplate.getExpire(redisKey, TimeUnit.SECONDS);
   337	                if (remainingTime != null && remainingTime <= 600) {
   338	                    redisTemplate.expire(redisKey, REDIS_TTL_MINUTES, TimeUnit.MINUTES);
   339	                    log.debug("Redis TTL 갱신: 사용자={}, 남은TTL={}초", email, remainingTime);
   340	                } else {
   341	                    log.debug("TTL 연장 불필요: 사용자={}, 남은TTL={}초", email, remainingTime);
   342	                }
   343	            }
   344	        } catch (Exception e) {
   345	            log.error("WebSocket 연결 TTL 갱신 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
   346	            throw new PaymentException(
   347	                    PaymentErrorCode.WEBSOCKET_CONNECTION_MAINTENANCE_FAILED,
   348	                    "WebSocket 연결 유지 중 오류가 발생했습니다.",
   349	                    e
   350	            );
   351	        }
   352	    }
   357	    private PaymentDTO toDTO(Payment notification) {
   358	        return PaymentDTO.builder()
   359	                .id(notification.getId())
   360	                .category(notification.getCategory())
   361	                .type(notification.getType())
   362	                .message(notification.getMessage())
   363	                .isRead(notification.isRead())
   364	                .createdAt(notification.getCreatedDate().toString())
   365	                .build();
   366	    }
   371	    private List<PaymentDTO> toDTOList(List<Payment> notifications) {
